1187	// Decode global dW tile index gt → (spec index s, m_atom, n_tile). Single-source.
1188	template <int N>
1189	__device__ __forceinline__ void dectc_dw_decode(
1190	        const DecDwSpec spec[9], int gt, int& s, int& m_atom, int& n_tile) {
1191	    int acc = 0;
1192	    for (s = 0; s < 9; ++s) {
1193	        const int ma = (spec[s].Nout + 63) / 64;
1194	        const int nt = (spec[s].Kin + N - 1) / N;
1195	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; return; }
1196	        acc += ma * nt;
1197	    }
1198	    s = 8; m_atom = 0; n_tile = 0;   // unreachable (gt < n_dw); keep defined
1199	}
1200	
1201	// PARTIAL dW for global tile gt over K-chunk kc of G → dw_part. K-chunk uses sp.K
1202	// (layer T / head B). FLOOR-BALANCED partition: chunk kc = [k0,k1) with
1203	// k0=floor(kc·KS/G), k1=floor((kc+1)·KS/G) — near-equal, summing to KS EXACTLY for
1204	// ANY KS≥G (no `G | KS` requirement → works at the production truncated B=4176,
1205	// where the head's KS=B/16 need NOT be divisible by G). A CEIL split would leave a
1206	// trailing EMPTY chunk whose slot stays unwritten → the reduce sums garbage (the
1207	// determinism-blind dW bug); floor never empties a chunk for KS≥G. Fresh ScaleD=0
1208	// per chunk → true partial. Writes the full 64×N tile (LOCAL rows) to the slot.
1209	template <int N>
1210	__device__ __forceinline__ void dectc_dw_run_tile_splitk(
1211	        const DecDwSpec spec[9], int gt, int kc, int G, float* __restrict__ dw_part,
1212	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1213	    int s, m_atom, n_tile;
1214	    dectc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1215	    const DecDwSpec& sp = spec[s];
1216	    const int mbase = m_atom * 64;
1217	    const int n0 = n_tile * N;
1218	    const int KS = sp.K / wgs::kWgmmaAtomK;                 // total k-atoms (T/16 or B/16)
1219	    const int k0 = (int)(((int64_t)kc       * KS) / G);     // floor-balanced chunk bounds
1220	    const int k1 = (int)(((int64_t)(kc + 1) * KS) / G);
1221	    const int kc_steps = k1 - k0;                          // sums to KS exactly over kc
1222	    float* slot = dw_part + ((int64_t)gt * G + kc) * kDecDwTileFloats;
1223	    // Empty-chunk guard (KS<G, i.e. B<64): a k_steps=0 GEMM would emit the
1224	    // uninitialized accumulator → zero the slot + return instead of running it
1225	    // (the reduce sums all G slots unconditionally, so an empty chunk MUST be 0).
1226	    if (kc_steps <= 0) {
1227	        for (int i = threadIdx.x; i < 64 * N; i += blockDim.x) slot[i] = 0.0f;
1228	        __syncthreads();
1229	        return;
1230	    }
1231	    const int Nout = sp.Nout, Kin = sp.Kin;
1232	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1233	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1234	        return m < Nout ? dY[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Nout + m] : __float2bfloat16(0.f); };
1235	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1236	        int nn = n0 + n; return nn < Kin ? X[(int64_t)(k0 * wgs::kWgmmaAtomK + k) * Kin + nn] : __float2bfloat16(0.f); };
1237	    // out(mbase+row, col, v): m is GLOBAL (srcA needs it); the slot holds only this
1238	    // atom's 64 LOCAL rows → index by (m - mbase). A `m<64` guard would never fire
1239	    // for m_atom>=1 → that slot stays UNWRITTEN (the rel~1.0 dW bug). Local-row fills it.
1240	    auto out  = [&] (int m, int n, float v) {
1241	        const int lr = m - mbase;
1242	        if (lr >= 0 && lr < 64 && n < N) slot[(int64_t)lr * N + n] = v; };
1243	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1244	        mbase, /*m_atoms=*/1, /*n_real=*/N, kc_steps, srcA, srcB, out, sA, sB);
1245	}
1246	
1247	// Deterministic reduce: output tile gt (% nCTA) sums its G chunk-partials ascending-kc
1248	// → grad. Same (gt → geometry) decode as the partial.
1249	template <int N>
1250	__device__ __forceinline__ void dectc_dw_reduce_splitk(
1251	        const DecDwSpec spec[9], int n_dw, int G, const float* __restrict__ dw_part,
1252	        float* __restrict__ grad, int cta, int nCTA) {
1253	    for (int gt = cta; gt < n_dw; gt += nCTA) {
1254	        int s, m_atom, n_tile;
1255	        dectc_dw_decode<N>(spec, gt, s, m_atom, n_tile);
1256	        const DecDwSpec& sp = spec[s];
1257	        const int mbase = m_atom * 64;
1258	        const int n0 = n_tile * N;
1259	        const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1260	        const int Nrow = (sp.Nout - mbase) < 64 ? (sp.Nout - mbase) : 64;
1261	        const int64_t base = (int64_t)gt * G * kDecDwTileFloats;
1262	        for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
1263	            const int row = idx / n_real, col = idx % n_real;
1264	            float accv = 0.0f;
1265	            for (int kc = 0; kc < G; ++kc)
1266	                accv += dw_part[base + (int64_t)kc * kDecDwTileFloats + (int64_t)row * N + col];
1267	            grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
1268	        }
1269	    }
1270	}
1271	
1272	// Biases db = Σ_K dY  (per output row). Work-stealing over the 9 weights' rows is
1273	// overkill; instead each CTA strides ALL bias outputs (cheap: ≤ 3d=384 rows × 9).
1274	// Single owner per output element (thread strides global bias-row index) → no atomics.
1275	__device__ __forceinline__ void dectc_dw_biases(
1276	        const DecDwSpec spec[9], float* __restrict__ grad) {
1277	    for (int s = 0; s < 9; ++s) {
1278	        const DecDwSpec& sp = spec[s];
1279	        for (int o = threadIdx.x; o < sp.Nout; o += blockDim.x) {
1280	            float accv = 0.0f;
1281	            for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1282	            grad[sp.bias_off + o] = accv;
1283	        }
1284	    }
1285	}
1286	
1287	// ════════════════════════════════════════════════════════════════════════
1288	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1289	//    tok grad: row r (token id) of tok.weight → owner CTA (r % nCTA); the owner
1290	//    scans ALL T tokens in ascending t, accumulating dh0[t,:] for tokens whose
1291	//    id == r. pos grad: row p → owner; sums dh0[t,:] over t with (t%S)==p.
1292	//    Fixed t-order + single owner per row → deterministic, atomic-free.
1293	//    `tok_ids` is HBM int32 [T]. Writes grad[tok_off..], grad[pos_off..].
1294	// ════════════════════════════════════════════════════════════════════════
1295	__device__ __forceinline__ void dectc_embed_owner_scan(
1296	        const DecActs& acts, const int* __restrict__ tok_ids, int T,
1297	        float* __restrict__ grad, int cta, int nCTA) {
1298	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1299	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1300	    // tok rows owned by this CTA: r in [0,V) with r % nCTA == cta.
1301	    for (int r = cta; r < dec::kVocab; r += nCTA) {
1302	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1303	            float accv = 0.0f;
1304	            for (int t = 0; t < T; ++t)
1305	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1306	            grad[tok_off + (int64_t)r * dec::kD + j] = accv;
1307	        }
1308	    }
1309	    // pos rows owned by this CTA: p in [0,S) with p % nCTA == cta.
1310	    for (int p = cta; p < dec::kSeq; p += nCTA) {
1311	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1312	            float accv = 0.0f;
1313	            for (int t = 0; t < T; ++t)
1314	                if ((t % dec::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1315	            grad[pos_off + (int64_t)p * dec::kD + j] = accv;
1316	        }
1317	    }
1318	}
1319	
1320	// ════════════════════════════════════════════════════════════════════════
1321	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
1322	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
1323	//    ASCENDING CTA index (deterministic) into the 10 dec_layout slots of grad.
1324	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1325	// ════════════════════════════════════════════════════════════════════════
1326	__device__ __forceinline__ void dectc_lnvec_reduce(
1327	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1328	        int nCTA, int cta) {
1329	    // Each CTA reduces a subset of the 10 LN tensors (round-robin by tensor).
1330	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1331	        const int goff = kLnVecTensorIdx[v];
1332	        const int64_t gbase = kDecOffsets[goff];
1333	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1334	            float accv = 0.0f;
1335	            for (int c = 0; c < nCTA; ++c)
1336	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * dec::kD + j];
1337	            grad[gbase + j] = accv;
1338	        }
1339	    }
1340	}
